def count_divisors_sq(n):
    # Find the prime factorization of n
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # tau(n^2) = product of (2*a_i + 1)
    count = 1
    for p in factors:
        a = factors[p]
        count *= (2 * a + 1)
    return count

