def count_y_less_than_x(x):
    x2 = x*x
    count = 0
    for d in range(1, int(x2**0.5) + 1):
        if x2 % d == 0:
            # Divisors are d and x2/d
            for div in [d, x2//d]:
                if x < div < 2*x:
                    count += 1
    return count

