def count_divisors_x_squared(n):
    d = {}
    temp = n
    i = 2
    while i * i <= temp:
        while temp % i == 0:
            d[i] = d.get(i, 0) + 1
            temp //= i
        i += 1
    if temp > 1:
        d[temp] = d.get(temp, 0) + 1
    res = 1
    for count in d.values():
        res *= (2 * count + 1)
    return res

